SELECT TblCase.CaseID, TblCase.Last_Name, TblCase.First_Name, qryOutstandingARRPT.CaseNo, qryOutstandingARRPT.Matter_type, qryOutstandingARRPT.Retainer, qryOutstandingARRPT.CaseOpenDate, qryOutstandingARRPT.Balance, qryOutstandingARRPT.[Balance Due Date], qryOutstandingARRPT.[Past Due], qryOutstandingARRPT.[Long Term Collections], qryOutstandingARRPT.chkBalanceDue, [qryOutstandingARRPT.Retainer]+[Balance] AS RetBal, qryOutstandingARRPT.Case_Letter, qryOutstandingARRPT.Orig_Atty, qryOutstandingARRPT.WriteOff
FROM TblCase INNER JOIN qryOutstandingARRPT ON TblCase.CaseID = qryOutstandingARRPT.CaseID;